<script setup lang="ts">import {computed,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {Sparkles,WandSparkles} from 'lucide-vue-next';import AppShell from '@/components/zs/AppShell.vue';import PageHeader from '@/components/zs/PageHeader.vue';import Panel from '@/components/zs/Panel.vue';import Field from '@/components/zs/Field.vue';import ZButton from '@/components/zs/ZButton.vue';import ScoreBadge from '@/components/crm/ScoreBadge.vue';import AIInsightCard from '@/components/crm/AIInsightCard.vue';import SequenceBuilder from '@/components/crm/SequenceBuilder.vue';import {useCrmData} from '@/composables/useCrmData';import type {SequenceStep} from '@/types/crm';import {setPageMeta} from '@/lib/page-meta';setPageMeta('AI Outreach Composer','Create personalized single emails and multi-step sequences.');const d=useCrmData(),route=useRoute(),router=useRouter(),selected=ref(String(route.query.lead??'')),name=ref('Operational efficiency'),objective=ref('Book a qualified discovery call'),tone=ref('Consultative'),count=ref(3),generated=ref(false),steps=ref<SequenceStep[]>([]);const lead=computed(()=>(d.leads.data.value??[]).find(x=>x.id===selected.value));function generate(){if(!lead.value)return;steps.value=Array.from({length:count.value},(_,i)=>({id:`draft-${i}`,subject:i===0?`A simpler operating system for ${lead.value?.company}`:i===1?'A quick follow-up':'Should I close the loop?',body:`Hi ${lead.value?.firstName},\n\n${i===0?`I noticed ${lead.value?.company} is growing in ${lead.value?.industry}. ZavSync can help address ${lead.value?.enrichment.painPoints[0]?.toLowerCase()}.`:`Following up with a concise idea tailored to ${lead.value?.company}.`}\n\nWould a short conversation be useful?`,delayDays:i===0?0:i===1?3:5}));generated.value=true}function transform(kind:string){steps.value=steps.value.map(x=>({...x,body:kind==='Shorten'?x.body.split('\n\n')[0]+'\n\nWould a quick call help?':kind==='Professional'?x.body.replace('Hi ','Dear '):x.body.replace('Would a short conversation be useful?',`Would a 20-minute review focused on ${lead.value?.industry.toLowerCase()} operations be useful?`)}))}</script>
<template><AppShell><PageHeader title="AI Outreach Composer" description="Create individualized outreach from CRM and enrichment context"><template #actions><ZButton variant="outline" @click="router.push('/outreach/automations')">View automations</ZButton></template></PageHeader><div class="grid gap-3 xl:grid-cols-[360px_1fr]"><div class="space-y-3"><Panel title="Lead context" body-class="p-4"><label><span class="label-caps">Lead</span><select v-model="selected" class="field mt-1.5"><option value="">Select a lead</option><option v-for="x in d.leads.data.value??[]" :key="x.id" :value="x.id">{{x.name}} — {{x.company}}</option></select></label><template v-if="lead"><div class="mt-4 flex items-center justify-between"><div><p class="text-sm font-semibold text-content">{{lead.name}}</p><p class="text-xs text-content-muted">{{lead.title}} · {{lead.company}}</p></div><ScoreBadge :score="lead.score.total"/></div><AIInsightCard class="mt-3" title="Personalization context" :content="lead.enrichment.valueProposition"/></template></Panel><Panel title="Sequence settings" body-class="space-y-4 p-4"><Field v-model="name" label="Sequence name"/><Field v-model="objective" label="Objective"/><label><span class="label-caps">Tone</span><select v-model="tone" class="field mt-1.5"><option>Consultative</option><option>Professional</option><option>Friendly</option><option>Direct</option></select></label><label><span class="label-caps">Number of steps</span><input v-model.number="count" type="number" min="1" max="5" class="field mt-1.5"/></label><ZButton class="w-full justify-center" :disabled="!lead" @click="generate"><Sparkles class="size-3.5"/>Generate sequence</ZButton></Panel></div><div><div v-if="generated" class="mb-3 flex flex-wrap gap-2"><ZButton variant="outline" @click="transform('Shorten')">Shorten</ZButton><ZButton variant="outline" @click="transform('Professional')">Make more professional</ZButton><ZButton variant="outline" @click="transform('Personalize')"><WandSparkles class="size-3.5"/>Personalize</ZButton><ZButton @click="router.push('/outreach/automations')">Save sequence</ZButton></div><SequenceBuilder v-if="generated" v-model="steps" @regenerate="i=>steps[i]&&(steps[i].body+='\n\nI can share a concise implementation plan.')"/><Panel v-else body-class="p-16 text-center"><Sparkles class="mx-auto size-8 text-content-muted"/><p class="mt-3 text-sm font-semibold text-content">Choose a lead and generate a sequence</p><p class="mt-1 text-xs text-content-muted">Messages use CRM facts and clearly reviewed AI enrichment context.</p></Panel></div></div></AppShell></template>
